{
  "name": "list_pages",
  "description": "List page ids + names. Result includes page_count, active_page_index, ids, and names as comma-separated strings.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "filePath": {
        "type": "string",
        "description": "Optional target .op file path; omit to use the server document"
      }
    }
  }
}
{
  "name": "read_nodes",
  "description": "Read nodes with depth control. Omit nodeIds to return top-level page children; depth=0 truncates children to \"...\", depth=-1 returns full subtrees. includeVariables=true attaches variables/themes JSON strings.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "filePath": {
        "type": "string",
        "description": "Optional target .op file path; omit to use the server document"
      },
      "nodeIds": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Node ids to read; omit for top-level children"
      },
      "depth": {
        "type": "number",
        "description": "0=node only, 1=direct children, -1=full subtree"
      },
      "pageId": {
        "type": "string"
      },
      "includeVariables": {
        "type": "boolean"
      }
    }
  }
}
{
  "name": "snapshot_layout",
  "description": "Get the hierarchical bounding box layout tree of the document. Use this to understand the current page structure, spatial arrangement, and node hierarchy before making changes.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "filePath": {
        "type": "string",
        "description": "Optional target .op file path; omit to use the server document"
      },
      "parentId": {
        "type": "string",
        "description": "Only return layout under this parent node"
      },
      "maxDepth": {
        "type": "number",
        "description": "Max depth to traverse (default 1)"
      },
      "pageId": {
        "type": "string",
        "description": "Target page ID (defaults to the active page)"
      }
    }
  }
}
{
  "name": "get_screenshot",
  "description": "Render a node to a PNG image for visual verification. nodeId may be \"root\" for the active page's top node.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "nodeId": {
        "type": "string",
        "description": "Node id, or \"root\""
      }
    },
    "required": [
      "nodeId"
    ]
  }
}
{
  "name": "lint_document",
  "description": "Run first-class OpenPencil design lint over the active document. Optionally filter to a node subtree.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "nodeId": {
        "type": "string",
        "description": "Optional node id to filter issues to that node and descendants"
      }
    }
  }
}
{
  "name": "get_node",
  "description": "Read a node by id with depth-limited descendants.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "node_id": {
        "type": "string",
        "description": "u64 node id"
      }
    },
    "required": [
      "node_id"
    ]
  }
}

