const url='http://127.0.0.1:3100/mcp';
const pages=[['n1317','n1318'],['n1319','n1320'],['n1321','n1322']];
let id=20;
async function call(name,args){const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json','accept':'application/json, text/event-stream','mcp-session-id':'openpencil'},body:JSON.stringify({jsonrpc:'2.0',id:id++,method:'tools/call',params:{name,arguments:args}})}); const j=await r.json(); if(j.error) throw Error(JSON.stringify(j.error)); return JSON.parse(j.result.content.find(x=>x.type==='text').text);}
function intersects(a,b){return Math.min(a.x+a.width,b.x+b.width)>Math.max(a.x,b.x)&&Math.min(a.y+a.height,b.y+b.height)>Math.max(a.y,b.y)}
for(const [pageId,rootId] of pages){const d=await call('read_nodes',{pageId,depth:1}); const root=d.nodes[0], c=root.children; const out=c.filter(n=>n.x<0||n.y<0||n.x+n.width>root.width||n.y+n.height>root.height).map(n=>n.id); const text=c.filter(n=>n.type==='text'); const overlaps=[]; for(let i=0;i<text.length;i++)for(let k=i+1;k<text.length;k++)if(intersects(text[i],text[k]))overlaps.push(`${text[i].id}/${text[k].id}`); console.log(JSON.stringify({pageId,rootId,size:`${root.width}x${root.height}`,childCount:c.length,outOfFrame:out,textTextOverlaps:overlaps,minFontSize:Math.min(...text.map(n=>n.fontSize)),maxBottom:Math.max(...c.map(n=>n.y+n.height)),maxRight:Math.max(...c.map(n=>n.x+n.width))}));}
